// ADR-023 routing table. EU inference profiles only (GDPR). Verified 2026-06-03.
const input = $input.first().json;
const importance = (input.importance || '').trim();

const SONNET = 'eu.anthropic.claude-sonnet-4-6';
const HAIKU  = 'eu.anthropic.claude-haiku-4-5-20251001-v1:0';
const OPUS   = 'eu.anthropic.claude-opus-4-5-20251101-v1:0'; // best Opus with account access; bump to 4-8 once granted

const CRITICAL_NUDGE = [
  'This task is CRITICALLY important to the company. Apply maximum effort:',
  'reason step by step, consider edge cases and failure modes, verify your',
  'reasoning before answering, and prioritise precision and correctness over',
  'brevity. Do not rush. Respond in the language of the task.',
  '', '---', ''
].join('\n');

// Fail-safe defaults (ADR-013): Sonnet on Bedrock-EU.
let model = SONNET, temperature = 0.7, maxTokens = 4000;
let prompt = input.prompt || '';

switch (importance) {
  case 'Niski':
    model = HAIKU; temperature = 0.7; maxTokens = 4000; break;
  case 'Średni':
    model = SONNET; temperature = 0.7; maxTokens = 4000; break;
  case 'Wysoki':
    model = OPUS; temperature = 0.5; maxTokens = 8000; break;
  case 'Krytycznie ważne':
    model = OPUS; temperature = 0.2; maxTokens = 16000;
    prompt = CRITICAL_NUDGE + prompt; break;
  default:
    // 'n/d - zadanie nie jest dla AI', empty, or unknown -> fail-safe Sonnet
    model = SONNET; temperature = 0.7; maxTokens = 4000;
}

return [{ json: {
  provider: 'bedrock-eu',
  model, temperature, maxTokens, prompt,
  importance, sensitivity: input.sensitivity || '', task_type: input.task_type || ''
} }];
